    /**
     * Render a public form with a fresh arithmetic captcha.
     *
     * @param  string  $slug  Public form slug.
     * @return  mixed  The form view.
     */
    public function show(string $slug)
    {
        $form = self::FORMS[$slug] ?? null;
        if (!$form) {
            abort(404);
        }

        $captcha = [random_int(1, 9), random_int(1, 9)];
        session(['fixzy_public_captcha' => $captcha]);

        return view('public.form', [
            'slug' => $slug,
            'form' => $form,
            'captcha' => $captcha,
            'lookupOptions' => $this->lookupOptionsFor($form),
        ]);
    }

    /**
     * Load select/radio options for lookup (FK) fields from the parent
     * tables. Keyed by field name => [id => label].
     */
    protected function lookupOptionsFor(array $form): array
    {
        $out = [];
        foreach ($form['fields'] as $f) {
            if (!empty($f['lookup'])) {
                $table = $f['lookup']['table'];
                $caption = $f['lookup']['caption'];
                $out[$f['name']] = DB::table($table)->orderBy($caption)->pluck($caption, 'id')->all();
            }
        }
        return $out;
    }

    /**
     * Handle a public form submission with rate limiting and honeypot checks.
     *
     * @param  Request  $request  Submitted form request.
     * @param  string  $slug  Public form slug.
     * @return  mixed  Redirect back with errors, or to the success page.
     */
    public function submit(Request $request, string $slug)
    {
        $form = self::FORMS[$slug] ?? null;
        if (!$form) {
            abort(404);
        }

        // Throttle: max 5 submissions per minute per IP.
        $key = 'public_form:' . $request->ip() . ':' . $slug;
        if (RateLimiter::tooManyAttempts($key, 5)) {
            return back()->withErrors(['throttle' => 'Too many submissions. Please wait a minute and try again.'])->onlyInput();
        }
        RateLimiter::hit($key, 60);

        // Honeypot: bots fill hidden fields; humans never see them.
        if ($request->input('website') !== null && $request->input('website') !== '') {
            // Silently drop bot submissions (don't reveal we caught them).
            return redirect()->route('public.form.success', ['slug' => $slug, 'ref' => 'submitted']);
        }

        // Captcha (optional, per-form).
        if ($form['captcha']) {
            $c = session('fixzy_public_captcha');
            $answer = $request->input('captcha');
            if (!is_array($c) || (int) $answer !== ((int) $c[0] + (int) $c[1])) {
                return back()->withErrors(['captcha' => 'Incorrect human-check answer. Please try again.'])->onlyInput();
            }
        }

        // Server-side validation mirroring the table schema (allowlist only).
        $rules = [];
        $attributes = [];
        foreach ($form['fields'] as $f) {
            $rules[$f['name']] = $f['rules'];
            if (!empty($f['item_rules'])) {
                $rules[$f['name'] . '.*'] = $f['item_rules'];
            }
            $attributes[$f['name']] = $f['label'];
        }
        $validated = $request->validate($rules, [], $attributes);

        // Build insert payload from the allowlist ONLY (never trust input keys).
        $payload = [];
        foreach ($form['fields'] as $f) {
            if (!array_key_exists($f['name'], $validated)) {
                continue;
            }
            $value = $validated[$f['name']];
            $ctrl = $f['control'] ?? '';

            // Uploaded files: store on the configured disk, save the path.
            if ($ctrl === 'image' || $ctrl === 'file') {
                if ($value instanceof \Illuminate\Http\UploadedFile) {
                    $disk = $f['storage'] ?? 'public';
                    $payload[$f['name']] = $value->store('public-form/' . $slug . '/' . $f['name'], $disk);
                }
                continue;
            }
            if ($ctrl === 'files') {
                $paths = [];
                foreach ((array) $value as $file) {
                    if ($file instanceof \Illuminate\Http\UploadedFile) {
                        $paths[] = $file->store('public-form/' . $slug . '/' . $f['name'], $f['storage'] ?? 'local');
                    }
                }
                // The model carries an 'array' cast for attachment columns —
                // pass the PHP array and let Eloquent serialize (json_encode
                // here would double-encode).
                $payload[$f['name']] = $paths ?: null;
                continue;
            }

            // Normalize datetime-local input ("2026-10-01T14:30") to a
            // storable "Y-m-d H:i:s" — raw T-form strings bypass
            // Carbon parsing and land in the DB unconverted.
            if ($ctrl === 'datetime' && is_string($value) && $value !== '') {
                $value = str_replace('T', ' ', $value);
                if (preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/', $value)) {
                    $value .= ':00';
                }
            }
            $payload[$f['name']] = $value;
        }

        // Status default (e.g. "pending") if the table has a status column.
        $statusField = $this->statusFieldFor($form['model']);
        if ($statusField && $form['status_default'] !== '') {
            $payload[$statusField] = $form['status_default'];
        }

        // Unique public reference (race-safe: retry on collision).
        $ref = $this->generateReference();
        $attempts = 0;
        while ($this->referenceExists($form['model'], $ref) && $attempts < 5) {
            $ref = $this->generateReference();
            $attempts++;
        }
        $payload['public_reference'] = $ref;

        $model = $form['model'];
        $record = $model::create($payload);

        return redirect()->route('public.form.success', ['slug' => $slug, 'ref' => $ref]);
    }

